import unittest
from solution import mask_rrn

class T(unittest.TestCase):
    def test_hyphen(self):
        self.assertEqual(mask_rrn("주민번호 900101-1234567 입니다"), "주민번호 900101-1****** 입니다")
    def test_plain(self):
        m = mask_rrn("9001011234567")
        self.assertIn(m, ("9001011******", "900101-1******"))
    def test_no_touch_longer(self):
        self.assertEqual(mask_rrn("01012345678901"), "01012345678901")
    def test_multiple(self):
        out = mask_rrn("a 900101-1234567 b 991231-2765432 c")
        self.assertEqual(out, "a 900101-1****** b 991231-2****** c")
    def test_no_match(self):
        self.assertEqual(mask_rrn("no numbers here"), "no numbers here")

if __name__ == "__main__":
    unittest.main()

