import unittest, random, time
from solution import best_schedule

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(best_schedule([(0,3,3),(2,5,4),(4,7,3)]), 6)
    def test_touching_ok(self):
        self.assertEqual(best_schedule([(0,3,3),(3,5,4)]), 7)
    def test_pick_one_big(self):
        self.assertEqual(best_schedule([(0,10,10),(0,3,3),(4,6,3),(7,9,3)]), 10)
    def test_empty(self):
        self.assertEqual(best_schedule([]), 0)
    def test_perf(self):
        random.seed(7)
        ms = []
        for _ in range(100000):
            s = random.randint(0, 10**7); d = random.randint(1, 1000)
            ms.append((s, s+d, random.randint(1, 100)))
        t0 = time.time()
        v = best_schedule(ms)
        self.assertLess(time.time() - t0, 10.0)
        self.assertGreater(v, 0)

if __name__ == "__main__":
    unittest.main()

