import unittest
from solution import summarize

LINES = [
    "2026-07-20T10:00:00Z GET /a 200 10ms",
    "2026-07-20T10:00:01Z GET /a 200 30ms",
    "2026-07-20T10:00:02Z GET /b 500 100ms",
    "2026-07-20T10:00:03Z POST /b 200 100ms",
    "broken line",
    "2026-07-20T10:00:04Z GET /c abc 10ms",
]

class T(unittest.TestCase):
    def setUp(self):
        self.s = summarize(LINES)
    def test_total(self):
        self.assertEqual(self.s["total"], 4)
    def test_by_status(self):
        self.assertEqual(self.s["by_status"], {200: 3, 500: 1})
    def test_slowest(self):
        self.assertEqual(self.s["slowest_path"], "/b")
    def test_error_rate(self):
        self.assertEqual(self.s["error_rate"], 0.25)
    def test_empty(self):
        s = summarize([])
        self.assertEqual(s["total"], 0)
        self.assertEqual(s["error_rate"], 0.0)

if __name__ == "__main__":
    unittest.main()

